solution.solution.cpp:
#include <algorithm>
#include <cmath>
#include <vector>

float sliderToAmplitude(int percent)
{
    percent = std::clamp(percent, 0, 100);
    if (percent == 0) return 0.0f;
    const float db{ -40.0f * (1.0f - percent / 100.0f) };
    return std::pow(10.0f, db / 20.0f);
}

float effectiveVolume(int master, int channel)
{
    return sliderToAmplitude(master) * sliderToAmplitude(channel);
}

class VoicePool
{
public:
    explicit VoicePool(int voices) : m_voices(static_cast<std::size_t>(voices)) {}

    int play(float now, float length)
    {
        int chosen{ -1 };
        for (std::size_t i{ 0 }; i < m_voices.size(); ++i)
            if (!m_voices[i].used || m_voices[i].start + m_voices[i].length <= now) { chosen = static_cast<int>(i); break; }
        if (chosen < 0)
        {
            chosen = 0;
            for (std::size_t i{ 1 }; i < m_voices.size(); ++i)
                if (m_voices[i].start < m_voices[static_cast<std::size_t>(chosen)].start) chosen = static_cast<int>(i);
        }
        m_voices[static_cast<std::size_t>(chosen)] = { true, now, length };
        return chosen;
    }

    int playing(float now) const
    {
        int n{ 0 };
        for (const Voice& v : m_voices) if (v.used && v.start + v.length > now) ++n;
        return n;
    }

private:
    struct Voice { bool used{ false }; float start{ 0 }; float length{ 0 }; };
    std::vector<Voice> m_voices;
};

unitTests:
TEST("slider") { CHECK_NEAR(sliderToAmplitude(100), 1.0, 1e-6); CHECK_NEAR(sliderToAmplitude(0), 0.0, 1e-9); CHECK_NEAR(sliderToAmplitude(50), 0.1, 1e-5); CHECK_NEAR(sliderToAmplitude(85), 0.50119, 1e-4); CHECK_NEAR(sliderToAmplitude(150), 1.0, 1e-6); CHECK_NEAR(sliderToAmplitude(-5), 0.0, 1e-9); }
TEST("master and channel") { CHECK_NEAR(effectiveVolume(50, 50), 0.01, 1e-6); CHECK_NEAR(effectiveVolume(100, 0), 0.0, 1e-9); }
TEST("free voices first") {
    VoicePool p{ 3 };
    CHECK_EQ(p.play(0.0f, 1.0f), 0); CHECK_EQ(p.play(0.1f, 1.0f), 1); CHECK_EQ(p.playing(0.5f), 2);
    CHECK_EQ(p.play(1.0f, 1.0f), 0); CHECK_EQ(p.playing(1.05f), 2);
}
TEST("stealing the oldest") {
    VoicePool p{ 2 }; p.play(0.0f, 5.0f); p.play(0.2f, 5.0f);
    CHECK_EQ(p.play(0.3f, 5.0f), 0); CHECK_EQ(p.play(0.4f, 5.0f), 1); CHECK_EQ(p.playing(0.5f), 2);
}

